import java.util.*;class GenericStack<T>{private final List<T> a=new ArrayList<>();void push(T x){a.add(x);}T pop(){if(a.isEmpty())throw new EmptyStackException();return a.remove(a.size()-1);}}public class GenericStackDemo{public static void main(String[]x){GenericStack<String>s=new GenericStack<>();s.push("Java");s.push("OOP");System.out.println(s.pop());GenericStack<Integer>n=new GenericStack<>();n.push(10);System.out.println(n.pop());}}
